CREATE TABLE IF NOT EXISTS app_plans (id TEXT PRIMARY KEY, grade TEXT NOT NULL, class_room TEXT NOT NULL, student_name TEXT NOT NULL, discovery_source TEXT NOT NULL, problem_summary TEXT NOT NULL, urgency_reason TEXT NOT NULL, public_benefit_reason TEXT NOT NULL, inquiry_question TEXT NOT NULL, screen_composition TEXT NOT NULL, features_to_implement TEXT NOT NULL, data_to_store TEXT NOT NULL, constraints TEXT NOT NULL, programming_principles TEXT NOT NULL, safety_checked INTEGER NOT NULL DEFAULT 0, rubric_level TEXT NOT NULL DEFAULT '미확인', teacher_note TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_app_plans_updated_at ON app_plans(updated_at DESC);
CREATE TABLE IF NOT EXISTS teacher_sessions (token_hash TEXT PRIMARY KEY, created_at TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_teacher_sessions_expires_at ON teacher_sessions(expires_at);
CREATE TABLE IF NOT EXISTS gallery_items (id TEXT PRIMARY KEY, student_id TEXT NOT NULL, student_name TEXT NOT NULL, app_url TEXT NOT NULL, intro TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_gallery_items_status_updated ON gallery_items(status, updated_at DESC);
CREATE TABLE IF NOT EXISTS app_plan_prompts (plan_id TEXT PRIMARY KEY, prompt_draft TEXT NOT NULL DEFAULT '', final_prompt TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_app_plan_prompts_updated_at ON app_plan_prompts(updated_at DESC);
CREATE TABLE IF NOT EXISTS app_revisions (id TEXT PRIMARY KEY, grade TEXT NOT NULL, class_room TEXT NOT NULL, student_name TEXT NOT NULL, before_image TEXT NOT NULL, before_code TEXT NOT NULL, after_code TEXT NOT NULL, after_image TEXT NOT NULL, reason_and_result TEXT NOT NULL, review_status TEXT NOT NULL DEFAULT '미확인', teacher_note TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_app_revisions_updated_at ON app_revisions(updated_at DESC);
CREATE TABLE IF NOT EXISTS app_plan_meta (plan_id TEXT PRIMARY KEY, student_number TEXT NOT NULL DEFAULT '', app_title TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_app_plan_meta_updated_at ON app_plan_meta(updated_at DESC);
CREATE TABLE IF NOT EXISTS app_revision_details (revision_id TEXT PRIMARY KEY, student_number TEXT NOT NULL DEFAULT '', tested_content TEXT NOT NULL DEFAULT '', fixed_after_test TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_app_revision_details_updated_at ON app_revision_details(updated_at DESC);
CREATE TABLE IF NOT EXISTS stage_evaluations (student_key TEXT PRIMARY KEY, discovery_rubric TEXT NOT NULL DEFAULT '미확인', discovery_note TEXT NOT NULL DEFAULT '', plan_rubric TEXT NOT NULL DEFAULT '미확인', plan_note TEXT NOT NULL DEFAULT '', revision_rubric TEXT NOT NULL DEFAULT '미확인', revision_note TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_stage_evaluations_updated_at ON stage_evaluations(updated_at DESC);
